with latest as (select distinct on (l."teamId") l."teamId" team_id, g.date, l.forwards||l.defensemen ids from "lineCombinations" l join games g on g.id=l."gameId" where g.date between '2026-11-01' and '2026-11-15' order by l."teamId", g.date desc), d as (select team_id, date, unnest(ids) pid from latest) select count(*) dressed, count(distinct team_id) teams, count(*) filter (where not exists (select 1 from rosters r where r."playerId"=d.pid and r."teamId"=d.team_id and r."seasonId"=20262027 and r.is_current)) not_on_team_current_roster, count(*) filter (where not exists (select 1 from rosters r where r."playerId"=d.pid and r."seasonId"=20262027)) no_roster_row_at_all, count(distinct team_id) filter (where not exists (select 1 from rosters r where r."playerId"=d.pid and r."teamId"=d.team_id and r."seasonId"=20262027 and r.is_current)) teams_affected, min(date) oldest_latest_lineup from d
